package com.daniil.wristlens.shared;
import android.content.Context;import android.graphics.*;import android.view.*;
/** Visible glyph 22dp, circular 48dp hit area. Hold releases on cancel or leaving hit area. */
public final class IconButton extends View {
 private final Paint paint=new Paint(3);private String icon;private int tint;private Runnable start,end;private boolean holding,down;public boolean allowHold;
 public IconButton(Context c,String icon,String label,Runnable action){super(c);this.icon=icon;tint=ThemeColors.accent(c);setContentDescription(label);setClickable(true);setFocusable(true);setOnClickListener(v->action.run());}
 private java.util.function.BooleanSupplier accessibilityAction;
 public void accessibilityAction(java.util.function.BooleanSupplier action){accessibilityAction=action;}
 @Override public CharSequence getAccessibilityClassName(){return android.widget.Button.class.getName();}
 @Override public boolean performAccessibilityAction(int action,android.os.Bundle args){if(action==android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK&&accessibilityAction!=null)return isEnabled()&&accessibilityAction.getAsBoolean();return super.performAccessibilityAction(action,args);}
 public void icon(String s,String label){icon=s;setContentDescription(label);invalidate();}public void tint(int c){tint=c;invalidate();}
 public void hold(Runnable begin,Runnable finish){start=begin;end=finish;}public boolean holding(){return holding;}
 private final Runnable longPress=()->{if(down&&allowHold){holding=true;ActionFeedback.perform(this,HapticFeedbackConstants.LONG_PRESS);if(start!=null)start.run();}};
 public void release(){removeCallbacks(longPress);down=false;if(holding){holding=false;if(end!=null)end.run();}invalidate();}
 @Override public boolean onTouchEvent(MotionEvent e){if(!allowHold&&!holding&&!down)return super.onTouchEvent(e);switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN->{if(!isEnabled())return false;down=true;postDelayed(longPress,350);invalidate();return true;}case MotionEvent.ACTION_MOVE->{if(e.getX()<0||e.getY()<0||e.getX()>getWidth()||e.getY()>getHeight())release();return true;}case MotionEvent.ACTION_UP->{boolean click=down&&!holding;release();if(click)performClick();return true;}case MotionEvent.ACTION_CANCEL->{release();return true;}default->{return true;}}}
 @Override public boolean performClick(){if(!isEnabled())return false;ActionFeedback.press(this);super.performClick();return true;}@Override protected void onDetachedFromWindow(){release();super.onDetachedFromWindow();}@Override public void onWindowFocusChanged(boolean has){super.onWindowFocusChanged(has);if(!has)release();}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float k=Math.min(getWidth(),getHeight())/48f;c.save();c.translate(getWidth()/2f,getHeight()/2f);c.scale(k,k);paint.setStyle(Paint.Style.FILL);paint.setColor(down?0xaa253344:0x73202a38);c.drawCircle(0,0,23,paint);paint.setColor(isEnabled()?tint:0x77ffffff);paint.setStrokeWidth(1.8f);paint.setStrokeCap(Paint.Cap.ROUND);paint.setStrokeJoin(Paint.Join.ROUND);paint.setStyle(Paint.Style.STROKE);
 switch(icon){case "mic_on", "mic_off"->{c.drawRoundRect(-4,-11,4,3,4,4,paint);c.drawArc(-8,-6,8,7,0,180,false,paint);c.drawLine(0,7,0,12,paint);c.drawLine(-4,12,4,12,paint);if(icon.equals("mic_off"))c.drawLine(-11,-11,11,11,paint);}case "photo"->{c.drawRoundRect(-11,-8,11,8,3,3,paint);c.drawCircle(0,0,4,paint);c.drawLine(-5,-8,-3,-11,paint);c.drawLine(-3,-11,4,-11,paint);}case "record"->{paint.setStyle(Paint.Style.FILL);c.drawCircle(0,0,10,paint);}case "video"->{c.drawRoundRect(-11,-7,5,7,2,2,paint);Path p=new Path();p.moveTo(5,-3);p.lineTo(12,-7);p.lineTo(12,7);p.lineTo(5,3);c.drawPath(p,paint);}case "stop"->{paint.setStyle(Paint.Style.FILL);c.drawRoundRect(-8,-8,8,8,2,2,paint);}case "pause"->{paint.setStrokeWidth(4);c.drawLine(-5,-8,-5,8,paint);c.drawLine(5,-8,5,8,paint);}case "play"->{Path p=new Path();p.moveTo(-5,-9);p.lineTo(10,0);p.lineTo(-5,9);p.close();c.drawPath(p,paint);}case "menu"->{for(int y=-7;y<=7;y+=7)c.drawLine(-10,y,10,y,paint);}case "flip"->{c.drawArc(-11,-11,11,11,25,135,false,paint);c.drawArc(-11,-11,11,11,205,135,false,paint);c.drawLine(10,-4,10,-11,paint);c.drawLine(10,-4,3,-5,paint);c.drawLine(-10,4,-10,11,paint);c.drawLine(-10,4,-3,5,paint);}case "phone"->{c.drawRoundRect(-7,-12,7,12,3,3,paint);c.drawLine(-2,8,2,8,paint);}case "gallery"->{c.drawRoundRect(-11,-9,11,9,2,2,paint);c.drawCircle(5,-4,2,paint);c.drawLine(-10,7,-3,-2,paint);c.drawLine(-3,-2,5,8,paint);}case "close"->{c.drawLine(-8,-8,8,8,paint);c.drawLine(-8,8,8,-8,paint);}default->{if(icon.startsWith("timer")){c.drawCircle(0,1,9,paint);c.drawLine(-3,-12,3,-12,paint);c.drawLine(0,1,0,-5,paint);c.drawLine(0,1,4,3,paint);String n=icon.substring(5);if(!n.equals("0")){paint.setTextSize(9);paint.setStyle(Paint.Style.FILL);paint.setTextAlign(Paint.Align.CENTER);c.drawText(n,10,15,paint);}}else{Path p=new Path();p.moveTo(2,-12);p.lineTo(-8,2);p.lineTo(0,2);p.lineTo(-2,12);p.lineTo(8,-2);p.lineTo(0,-2);p.close();c.drawPath(p,paint);if(icon.equals("flash_off"))c.drawLine(-11,-11,11,11,paint);if(icon.equals("flash_auto")||icon.equals("flash_torch")){paint.setStyle(Paint.Style.FILL);paint.setTextSize(8);c.drawText(icon.equals("flash_auto")?"A":"∞",8,12,paint);}}}}
 c.restore();}
}
